package kr.memorynotes;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.view.*;import android.widget.*;import android.text.*;import org.json.*;import java.util.*;import java.time.LocalDate;import java.io.*;
public class MainActivity extends Activity {
 SpeechReader speech; Ui u; NoteDb db; LinearLayout root,content; String page="홈",subjectFilter=""; NoteEditor editor; ReviewScreen review; Runnable backAction; boolean busy=false;String pendingImageNote;AlertDialog busyDialog;
 void startBusy(String message){busy=true;busyDialog=new AlertDialog.Builder(this).setMessage(message).setCancelable(false).create();busyDialog.show();}
 void endBusy(){busy=false;if(busyDialog!=null){busyDialog.dismiss();busyDialog=null;}}
 public void onCreate(Bundle b){super.onCreate(b);db=new NoteDb(this);u=new Ui(this);if(b!=null){page=b.getString("page","홈");subjectFilter=b.getString("subject","");}show(page);}
 protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("page",page);b.putString("subject",subjectFilter);}
 public void onConfigurationChanged(android.content.res.Configuration c){super.onConfigurationChanged(c);}
 protected void onPause(){if(editor!=null)editor.persistDraft();super.onPause();}
 protected void onDestroy(){if(speech!=null)speech.detach();super.onDestroy();}
 void shell(String title,String subtitle,boolean nav){shell(title,subtitle,nav,false);}
 void shell(String title,String subtitle,boolean nav,boolean fixed){if(speech!=null)speech.close();u=new Ui(this);getWindow().setStatusBarColor(u.bg);getWindow().setNavigationBarColor(u.bg);getWindow().getDecorView().setSystemUiVisibility(getPreferences(0).getBoolean("dark",false)?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);root=u.col();root.setBackgroundColor(u.bg);root.setPadding(0,0,0,0);root.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(in.getSystemWindowInsetLeft(),in.getSystemWindowInsetTop(),in.getSystemWindowInsetRight(),in.getSystemWindowInsetBottom());return in.consumeSystemWindowInsets();});setContentView(root);LinearLayout head=u.col();head.setPadding(u.dp(22),u.dp(14),u.dp(22),u.dp(4));if(!nav)head.addView(u.button("‹ 돌아가기",()->onBackPressed()));head.addView(u.text("MEMORY NOTE",11,u.green));head.addView(u.title(title));if(!subtitle.isEmpty())head.addView(u.text(subtitle,14,u.muted));root.addView(head);content=u.col();content.setPadding(u.dp(20),u.dp(6),u.dp(20),u.dp(10));if(fixed){root.addView(content,new LinearLayout.LayoutParams(-1,0,1));}else{ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setVerticalScrollBarEnabled(true);scroll.setScrollbarFadingEnabled(false);scroll.setSmoothScrollingEnabled(true);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}if(nav){LinearLayout bar=u.row();bar.setPadding(u.dp(6),u.dp(5),u.dp(6),u.dp(7));bar.setBackgroundColor(u.surface);for(String p:new String[]{"홈","과목","오답","검색","설정"}){Button b=u.navigation(p,p.equals(page),()->{subjectFilter="";show(p);});b.setTextSize(12*u.scale);if(p.equals(page))b.setTypeface(null,android.graphics.Typeface.BOLD);u.weighted(bar,b);}root.addView(bar);}}
 void startListening(ArrayList<Note> notes){if(speech!=null)speech.close();speech=new SpeechReader(this);speech.open(notes);}
 void show(String p){editor=null;review=null;backAction=null;page=p;switch(p){case "홈":home();break;case "과목":subjects();break;case "오답":listPage(true);break;case "검색":listPage(false);break;default:settings();}}
 String groupName(String table,String id){String name=db.groups(table,null).get(id);return name==null?"미분류":name;}
 String meta(Note n){return groupName("subjects",n.subject)+" · "+(n.chapter.isEmpty()?"단원 없음":groupName("chapters",n.chapter))+" · "+n.type;}
 String rating(Note n){return n.rating<0?"새 노트":new String[]{"모름","헷갈림","외웠음"}[n.rating];}
 ArrayList<Note> filtered(){ArrayList<Note> out=db.query("");if(!subjectFilter.isEmpty())out.removeIf(n->!n.subject.equals(subjectFilter));return out;}
 boolean due(Note n){return NoteFilter.isDue(n,LocalDate.now().toString());}
 LinearLayout scrollingNotes(LinearLayout parent){ScrollView scroll=new ScrollView(this);scroll.setTag("note.list");scroll.setFillViewport(true);scroll.setVerticalScrollBarEnabled(true);scroll.setScrollbarFadingEnabled(false);LinearLayout list=u.col();list.setTag("note.results");scroll.addView(list);parent.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));return list;}
 void home(){
  shell("오늘도, 한 장씩","",true,true);ArrayList<Note> notes=db.query("");long count=notes.stream().filter(this::due).count();
  LinearLayout hero=u.card(content);hero.setTag("home.header");hero.addView(u.text(LocalDate.now()+" · 오늘의 복습",12,u.muted));hero.addView(u.text(count+"개의 기억을 꺼낼 시간",21,u.ink));TextView summary=u.text("전체 노트 "+notes.size()+"개 · 오늘 복습 "+count+"개",14,u.green);summary.setTag("home.summary");hero.addView(summary);
  LinearLayout actions=u.row();u.weighted(actions,u.primary("오늘 복습",()->startReview(true,"")));u.weighted(actions,u.button("전체 복습 · 범위",()->new ReviewPicker(this,false,"")));hero.addView(actions);
  LinearLayout tools=u.row();u.weighted(tools,u.primary("＋ 새 노트",()->edit(null)));u.weighted(tools,u.button("▶ 읽어주기",()->startListening(db.query(""))));content.addView(tools);
  String draft=getPreferences(0).getString("draft","");if(!draft.isEmpty())content.addView(u.button("작성 중인 노트 이어쓰기",()->{try{edit(Note.from(new JSONObject(draft)));}catch(Exception e){error(e);}}));
  content.addView(u.text("정리한 노트 · 전체 "+notes.size()+"개",17,u.ink));LinearLayout list=scrollingNotes(content);if(notes.isEmpty())list.addView(u.text("첫 노트를 만들어보세요.",16,u.muted));for(Note n:notes)noteCard(list,n);
 }
 void empty(String title,String msg){LinearLayout c=u.card(content);c.addView(u.text(title,18,u.ink));c.addView(u.text(msg,14,u.muted));}
 void noteCard(LinearLayout p,Note n){LinearLayout c=u.card(p);c.addView(u.text(meta(n),11,u.muted));TextView t=u.text((n.favorite?"★ ":"")+n.title,18,u.ink);t.setTypeface(null,android.graphics.Typeface.BOLD);c.addView(t);String desc=Cloze.mask(InlineImageText.readable(n.type.equals("일반 노트")?n.body:n.question));if(!desc.isEmpty()){TextView excerpt=u.text(desc,14,u.muted);excerpt.setMaxLines(2);excerpt.setEllipsize(TextUtils.TruncateAt.END);c.addView(excerpt);}c.addView(u.text(rating(n)+(n.images.length()>0?"  ·  사진 "+n.images.length()+"장":"")+(n.due.isEmpty()?"":"  ·  복습 "+n.due),12,u.green));c.setOnClickListener(v->detail(n));}
 void subjects(){shell("과목별 노트","공조냉동부터 새로운 공부까지",true);content.addView(u.primary("＋ 과목 추가",()->nameDialog("과목 추가","",name->{db.addGroup("subjects",name,null);subjects();})));for(Map.Entry<String,String> e:db.groups("subjects",null).entrySet()){LinearLayout c=u.card(content);long count=db.query("").stream().filter(n->n.subject.equals(e.getKey())).count();c.addView(u.text(e.getValue(),21,u.ink));c.addView(u.text(count+"개의 노트",13,u.muted));c.addView(u.button("노트 보기 →",()->{subjectFilter=e.getKey();listPage(false);}));LinearLayout r=u.row();u.weighted(r,u.button("단원 관리",()->chapters(e.getKey())));u.weighted(r,u.button("이름 변경",()->nameDialog("과목 이름",e.getValue(),name->{db.renameGroup("subjects",e.getKey(),name);subjects();})));c.addView(r);}}
 interface NameAction{void run(String name);}
 void nameDialog(String title,String old,NameAction action){EditText e=new EditText(this);e.setSingleLine();e.setText(old);AlertDialog d=new AlertDialog.Builder(this).setTitle(title).setView(e).setNegativeButton("취소",null).setPositiveButton("저장",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{String name=e.getText().toString().trim();if(name.isEmpty()){e.setError("이름을 입력하세요");return;}action.run(name);d.dismiss();}));d.show();}
 void chapters(String subject){shell(groupName("subjects",subject),"단원 관리 · 이름을 바꿔도 노트는 유지돼요.",false);backAction=()->show("과목");content.addView(u.primary("＋ 단원 추가",()->nameDialog("단원 추가","",name->{db.addGroup("chapters",name,subject);chapters(subject);})));for(Map.Entry<String,String> e:db.groups("chapters",subject).entrySet()){LinearLayout c=u.card(content);c.addView(u.text(e.getValue(),18,u.ink));c.addView(u.button("이름 변경",()->nameDialog("단원 이름",e.getValue(),name->{db.renameGroup("chapters",e.getKey(),name);chapters(subject);})));}}
 void listPage(boolean mistakes){
  page=mistakes?"오답":"검색";shell(mistakes?"실수를, 내 것으로":"노트 찾기","",true,true);
  LinearLayout controls=u.card(content);controls.setPadding(u.dp(12),u.dp(8),u.dp(12),u.dp(6));EditText query=u.edit(controls,"검색어","",1);query.setTag("search.query");FilterControls filters=new FilterControls(this,controls,subjectFilter,mistakes);
  TextView count=u.text("",14,u.green);count.setTag("search.count");content.addView(count);
  LinearLayout actions=u.row();u.weighted(actions,u.button("선택 복습",()->beginReview(filters.selection().select(db.query(query.getText().toString()),LocalDate.now().toString()))));u.weighted(actions,u.button("▶ 읽기",()->startListening(filters.selection().select(db.query(query.getText().toString()),LocalDate.now().toString()))));u.weighted(actions,u.primary("＋ 새 노트",()->edit(null)));content.addView(actions);
  LinearLayout results=scrollingNotes(content);Runnable render=()->{results.removeAllViews();ArrayList<Note> matches=filters.selection().select(db.query(query.getText().toString()),LocalDate.now().toString());count.setText("검색 결과 "+matches.size()+"개 / 전체 "+db.query("").size()+"개");for(Note n:matches)noteCard(results,n);if(matches.isEmpty())results.addView(u.text("조건에 맞는 노트가 없습니다.",16,u.muted));};filters.changed=render;query.addTextChangedListener(watcher(render));render.run();
 }
 static TextWatcher watcher(Runnable r){return new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){r.run();}public void afterTextChanged(Editable e){}};}
 static AdapterView.OnItemSelectedListener listener(Runnable r){return new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int pos,long id){r.run();}public void onNothingSelected(AdapterView<?> p){}};}
 void edit(Note n){
  String draft=getPreferences(0).getString("draft","");
  if(!draft.isEmpty()){try{Note pending=Note.from(new JSONObject(draft));if(n!=null&&n.id.equals(pending.id)){openEditor(pending);return;}new AlertDialog.Builder(this).setTitle("작성 중인 노트가 있습니다").setMessage("초안을 이어 쓰거나 버린 뒤 다른 노트를 작성할 수 있습니다.").setNegativeButton("취소",null).setNeutralButton("초안 이어쓰기",(d,w)->openEditor(pending)).setPositiveButton("초안 버리고 작성",(d,w)->{getPreferences(0).edit().remove("draft").apply();openEditor(n);}).show();return;}catch(Exception e){error(e);return;}}
  openEditor(n);
 }
 void openEditor(Note n){review=null;backAction=null;editor=new NoteEditor(this,n);editor.show();}
 void detail(Note n){editor=null;review=null;shell(n.type.equals("문답 카드")?"문답 노트":n.title,meta(n),false);backAction=()->show(page);u.pictures=n.images;if(n.type.equals("일반 노트")){
  u.section(content,"내용",0).addView(u.studyContent(n.body,18,true,false));
 }else{
  u.section(content,"문제 · 질문",0).addView(u.text(n.question,19,u.ink));
  if(n.type.equals("오답노트")&&!n.mine.isEmpty())u.section(content,"내가 쓴 답",3).addView(u.text(n.mine,18,u.ink));
  u.section(content,"정답 · 해설",0).addView(u.studyContent(n.answer,18,true,false));
  if(n.type.equals("오답노트")&&!n.body.isEmpty())u.section(content,"내용 · 추가 메모",0).addView(u.studyContent(n.body,18,true,false));
 }
 if(!n.reason.isEmpty())u.section(content,"틀린 점 · 헷갈린 이유",1).addView(u.text(n.reason,18,u.ink));
 if(!n.caution.isEmpty())u.section(content,"주의사항 · 다음에 확인할 것",2).addView(u.text(n.caution,18,u.ink));
 if(!n.tags.isEmpty())u.section(content,"태그",3).addView(u.text(n.tags,15,u.ink));
 if(ImageMaskView.hasSeparateImages(n))ImageMaskView.appendImages(this,u.section(content,"첨부 사진",3),n,false,false);
 LinearLayout actions=u.row();u.weighted(actions,u.primary("수정",()->edit(n)));u.weighted(actions,u.button(n.favorite?"★ 즐겨찾기 해제":"☆ 즐겨찾기",()->{n.favorite=!n.favorite;try{db.save(n);detail(n);}catch(Exception e){error(e);}}));content.addView(actions);if(SpeechText.eligible(n.images.length()))content.addView(u.button("▶ 이 문제 읽어주기",()->startListening(new ArrayList<>(java.util.Collections.singletonList(n)))));content.addView(u.button("이 노트 복습",()->{ArrayList<Note> one=new ArrayList<>();one.add(n);review=new ReviewScreen(this,one);review.show();}));if(!n.type.equals("오답노트"))content.addView(u.button("오답노트로 전환",()->{n.type="오답노트";edit(n);}));content.addView(u.button("노트 삭제",()->u.confirm("노트 삭제","이 노트와 복습 이력을 삭제할까요?",()->{db.delete(n);show(page);})));}
 void startReview(boolean onlyDue,String subject){NoteFilter f=new NoteFilter();f.subject=subject;f.dueOnly=onlyDue;beginReview(f.select(db.query(""),LocalDate.now().toString()));}
 void beginReview(ArrayList<Note> notes){notes.sort(Comparator.comparingInt((Note n)->n.rating==0?0:n.rating==1?1:2).thenComparing(n->n.due));if(notes.isEmpty()){u.message("선택한 조건에 복습할 노트가 없습니다. 범위를 바꿔보세요.");return;}editor=null;review=new ReviewScreen(this,notes);review.show();}
 void settings(){shell("내 공부 설정","편하게 읽고, 안전하게 보관하세요.",true);LinearLayout c=u.card(content);c.addView(u.text("화면",19,u.ink));Switch dark=new Switch(this);dark.setText("다크모드");dark.setTextColor(u.ink);dark.setChecked(getPreferences(0).getBoolean("dark",false));if(dark.isChecked()){int[][] states={new int[]{android.R.attr.state_checked},new int[]{}};dark.setThumbTintList(new android.content.res.ColorStateList(states,new int[]{u.green,u.muted}));dark.setTrackTintList(new android.content.res.ColorStateList(states,new int[]{android.graphics.Color.parseColor("#395A55"),u.line}));}c.addView(dark);dark.setOnCheckedChangeListener((v,on)->{getPreferences(0).edit().putBoolean("dark",on).apply();settings();});float font=getPreferences(0).getFloat("font",1);Spinner size=u.spinner(c,"글자 크기",new String[]{"기본","크게","아주 크게"},font>1.2?2:font>1?1:0);size.setOnItemSelectedListener(listener(()->{float f=new float[]{1,1.15f,1.3f}[size.getSelectedItemPosition()];if(f!=getPreferences(0).getFloat("font",1)){getPreferences(0).edit().putFloat("font",f).apply();settings();}}));LinearLayout backup=u.card(content);backup.addView(u.text("백업 · 복원",19,u.ink));backup.addView(u.text("노트, 사진, 가림 영역, 복습 기록을 함께 보관합니다. 앱 삭제 전 백업 파일을 별도로 저장하세요.",14,u.muted));backup.addView(u.primary("백업 파일 저장",()->{if(busy)return;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/zip");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"암기노트-"+LocalDate.now()+".zip");startActivityForResult(i,20);}));backup.addView(u.button("백업에서 복원",()->u.confirm("백업 복원","현재 노트와 사진이 백업 내용으로 대체됩니다. 먼저 현재 데이터를 백업했는지 확인하세요.",()->{if(busy)return;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,21);})));LinearLayout stat=u.card(content);stat.addView(u.text("학습 통계",19,u.ink));ArrayList<Note> notes=db.query("");for(Map.Entry<String,String> s:db.groups("subjects",null).entrySet())stat.addView(u.text(s.getValue()+"  "+notes.stream().filter(n->n.subject.equals(s.getKey())).count()+"개",15,u.ink));for(int r=-1;r<=2;r++){final int rr=r;stat.addView(u.text((r<0?"새 노트":new String[]{"모름","헷갈림","외웠음"}[r])+"  "+notes.stream().filter(n->n.rating==rr).count()+"개",14,u.muted));}u.gap(stat,10);stat.addView(u.text("최근 30개 학습일 · 복습 횟수",14,u.ink));for(Map.Entry<String,Integer> h:db.history().entrySet())stat.addView(u.text(h.getKey()+"   "+h.getValue()+"회",14,u.muted));content.addView(u.text("암기노트 1.4.5 · 오프라인 개인 학습\n사진 가리기와 빈칸은 직접 지정합니다.",12,u.muted));}
 void chooseImages(){if(editor==null||busy)return;pendingImageNote=editor.note.id;editor.persistDraft();Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,10);}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null)return;if(req==10){if(editor==null){try{String draft=getPreferences(0).getString("draft","");if(!draft.isEmpty())edit(Note.from(new JSONObject(draft)));}catch(Exception e){error(e);}}if(editor==null)return;final NoteEditor target=editor;ArrayList<Uri> uris=new ArrayList<>();if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)uris.add(data.getData());startBusy("사진을 가져오는 중입니다…");new Thread(()->{ArrayList<String> files=new ArrayList<>();Exception failure=null;try{for(Uri uri:uris){files.add(ImageMaskView.importImage(this,uri));}}catch(Exception e){failure=e;}Exception error=failure;runOnUiThread(()->{endBusy();for(String file:files)target.addImage(file);if(error!=null)error(error);});}).start();}else if(req==20||req==21){Uri uri=data.getData();if(uri==null||busy)return;startBusy(req==20?"백업 저장 중…":"백업 검사 및 복원 중…");new Thread(()->{Exception failure=null;try{BackupManager bm=new BackupManager(this,db);if(req==20){try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("파일을 열 수 없습니다");bm.exportTo(out);}}else{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("파일을 열 수 없습니다");bm.validateAndRestore(in);}}}catch(Exception e){failure=e;}Exception error=failure;runOnUiThread(()->{endBusy();if(error!=null)error(error);else{if(req==21)getPreferences(0).edit().remove("draft").apply();show("설정");u.message(req==20?"사진을 포함한 백업을 저장했습니다.":"백업 복원을 완료했습니다.");}});}).start();}}
 void error(Exception e){u.message("처리하지 못했습니다. 기존 저장 내용은 유지됩니다.\n"+(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage()));}
 @Override public void onBackPressed(){if(busy){Toast.makeText(this,"작업을 마칠 때까지 잠시 기다려주세요.",Toast.LENGTH_SHORT).show();return;}if(editor!=null){editor.leave();return;}if(backAction!=null){Runnable r=backAction;backAction=null;r.run();return;}if(!page.equals("홈")){show("홈");return;}super.onBackPressed();}
}
